-- Idempotent seed data - run after 02_schema.sql
-- Passwords are bcrypt hashes (cost 12) generated by backend bcrypt dependency
-- Password for all seeded users: <Role>Pass123! (e.g., AdminPass123!, OwnerPass123!, UserPass123!)
-- Names satisfy the 20-60 character validation rule

-- Users (1 Admin, 2 Store Owners, 3 Normal Users)
INSERT INTO users (id, name, email, password_hash, address, role)
SELECT
    uuid_generate_v4(),
    'System Administrator Roxiler',
    'admin@roxiler.com',
    '$2a$10$enkU6AgsNhUdbNuZX9jghOhqHn3M5NPL8YX4iBs8ZkzaTIPnja2Oi',
    'Roxiler Systems, 5th Floor, Cyber Towers, HITEC City, Hyderabad 500081',
    'SYSTEM_ADMIN'
ON CONFLICT (email) DO NOTHING;

