-- Sample Ratings (Ananya rated electronics 5 stars, Vikram 4 stars, etc.)
INSERT INTO ratings (id, user_id, store_id, rating)
SELECT
    uuid_generate_v4(),
    (SELECT id FROM users WHERE email = 'ananya.bhattacharya@roxiler.com' LIMIT 1),
    (SELECT id FROM stores WHERE email = 'priya.electronics@roxiler.com' LIMIT 1),
    5
ON CONFLICT (user_id, store_id) DO UPDATE SET rating = EXCLUDED.rating;

